CREATE DATABASE IF NOT EXISTS vitc_hospital
  CHARACTER SET utf8mb4
  COLLATE utf8mb4_unicode_ci;

USE vitc_hospital;

DROP TABLE IF EXISTS appointments;
DROP TABLE IF EXISTS emergency_requests;
DROP TABLE IF EXISTS contacts;
DROP TABLE IF EXISTS patients;
DROP TABLE IF EXISTS doctors;

CREATE TABLE patients (
  id          INT            NOT NULL AUTO_INCREMENT,
  name        VARCHAR(120)   NOT NULL,
  age         TINYINT        NOT NULL,
  gender      ENUM('male','female','other') NOT NULL DEFAULT 'other',
  blood_group VARCHAR(5)     DEFAULT 'O+',
  `condition` VARCHAR(255)   DEFAULT NULL,
  phone       VARCHAR(20)    DEFAULT NULL,
  status      ENUM('active','admitted','discharged') NOT NULL DEFAULT 'active',
  created_at  TIMESTAMP      NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at  TIMESTAMP      NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE doctors (
  id                 INT          NOT NULL AUTO_INCREMENT,
  name               VARCHAR(120) NOT NULL,
  specialty          VARCHAR(100) NOT NULL,
  phone              VARCHAR(20)  DEFAULT NULL,
  email              VARCHAR(120) DEFAULT NULL,
  experience         TINYINT      DEFAULT 0,
  status             ENUM('available','on_leave','off_duty') NOT NULL DEFAULT 'available',
  consultation_hours VARCHAR(120) DEFAULT NULL,
  available_dates    TEXT         DEFAULT NULL,
  created_at         TIMESTAMP    NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at         TIMESTAMP    NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE appointments (
  id               INT          NOT NULL AUTO_INCREMENT,
  patient_name     VARCHAR(120) NOT NULL,
  age              TINYINT      DEFAULT NULL,
  phone            VARCHAR(20)  DEFAULT NULL,
  gender           VARCHAR(10)  DEFAULT NULL,
  doctor_id        INT          NOT NULL,
  doctor_name      VARCHAR(120) NOT NULL,
  appointment_date DATE         NOT NULL,
  appointment_time VARCHAR(20)  DEFAULT NULL,
  reason           TEXT         DEFAULT NULL,
  notes            TEXT         DEFAULT NULL,
  status           ENUM('pending','approved','rejected') NOT NULL DEFAULT 'pending',
  created_at       TIMESTAMP    NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at       TIMESTAMP    NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (id),
  FOREIGN KEY (doctor_id) REFERENCES doctors(id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE emergency_requests (
  id           INT          NOT NULL AUTO_INCREMENT,
  patient_name VARCHAR(120) NOT NULL,
  phone        VARCHAR(20)  DEFAULT NULL,
  location     VARCHAR(255) NOT NULL,
  description  TEXT         DEFAULT NULL,
  role         ENUM('patient','admin') NOT NULL DEFAULT 'patient',
  status       ENUM('active','resolved') NOT NULL DEFAULT 'active',
  created_at   TIMESTAMP    NOT NULL DEFAULT CURRENT_TIMESTAMP,
  resolved_at  TIMESTAMP    NULL DEFAULT NULL,
  PRIMARY KEY (id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE contacts (
  id         INT          NOT NULL AUTO_INCREMENT,
  department VARCHAR(120) NOT NULL,
  head_name  VARCHAR(120) DEFAULT NULL,
  phone      VARCHAR(30)  DEFAULT NULL,
  email      VARCHAR(120) DEFAULT NULL,
  created_at TIMESTAMP    NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;





